style.css:
/* Dark Theme for Magister */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("magister.net"), domain("magister.nl") {
/* Backgrounds */
  body, .wrapper, #main, .container {
    background: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* Headers, navbars */
  header, nav, .topbar, .sidebar {
    background: #1e1e1e !important;
    border-color: #333 !important;
  }

  /* Cards, panels */
  .card, .panel, .module, .widget {
    background: #1c1c1c !important;
    border: 1px solid #333 !important;
  }

  /* Text and links */
  a, .link, .nav-link {
    color: #81a1c1 !important;
  }
  a:hover, .link:hover {
    color: #8fbcbb !important;
  }

  /* Buttons */
  button, .btn {
    background: #2a2a2a !important;
    color: #e0e0e0 !important;
    border: 1px solid #444 !important;
  }
  button:hover, .btn:hover {
    background: #3a3a3a !important;
  }

  /* Inputs, selects, textareas */
  input, select, textarea {
    background: #1a1a1a !important;
    color: #e0e0e0 !important;
    border: 1px solid #333 !important;
  }
  input:focus, textarea:focus, select:focus {
    border-color: #81a1c1 !important;
    box-shadow: 0 0 2px #81a1c1 !important;
  }

  /* Tables */
  table {
    background: #1a1a1a !important;
    color: #e0e0e0 !important;
    border-color: #333 !important;
  }
  th, td {
    border-color: #333 !important;
  }
  tr:nth-child(even) {
    background: #1e1e1e !important;
  }

  /* Scrollbars (Firefox) */
  * {
    scrollbar-width: thin;
    scrollbar-color: #444 #1a1a1a;
  }

  /* Scrollbars (WebKit) */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #555;
  }

  /* Notifications / alerts */
  .alert, .notification {
    background: #2b2b2b !important;
    border-color: #444 !important;
    color: #e0e0e0 !important;
  }

  /* Links inside cards/panels */
  .card a, .panel a {
    color: #88c0d0 !important;
  }

  /* Logo / images – invert if needed */
  .logo img {
    filter: brightness(0) invert(1) !important;
  }
}
